const PLACE_IDS = Object.keys(PLACES);
function placeGet(id){ const p = PLACES[id]; return p ? { id:id, name:p[0], abbr:p[1], kind:p[2], lat:p[3], lon:p[4], prom:p[5], land:p[6], who:p[7], flags:p[8], blurb:p[9] } : null; }
